1205|  (*token)++;
1206|
1207|  // i//k
1208|  if ((*token)[0] == '/') {
1209|    (*token)++;
1210|    if (!fixIndex(atoi((*token)), vnsize, &vi.vn_idx, true, context)) {
1211|      return false;
1212|    }
1213|    (*token) += strcspn((*token), "/ \t\r");
1214|    (*ret) = vi;
1215|    return true;
1216|  }
1217|
1218|  // i/j/k or i/j
1219|  if (!fixIndex(atoi((*token)), vtsize, &vi.vt_idx, true, context)) {
1220|    return false;
1221|  }
1222|
1223|  (*token) += strcspn((*token), "/ \t\r");
1224|  if ((*token)[0] != '/') {
1225|    (*ret) = vi;
1226|    return true;
1227|  }
1228|
1229|  // i/j/k
1230|  (*token)++;  // skip '/'
1231|  if (!fixIndex(atoi((*token)), vnsize, &vi.vn_idx, true, context)) {
1232|    return false;
1233|  }
1234|  (*token) += strcspn((*token), "/ \t\r");
1235|
1236|  (*ret) = vi;
1237|
1238|  return true;
