1452|struct TinyObjPoint {
1453|  real_t x, y, z;
1454|  TinyObjPoint() : x(0), y(0), z(0) {}
1455|  TinyObjPoint(real_t x_, real_t y_, real_t z_) : x(x_), y(y_), z(z_) {}
