1476|inline TinyObjPoint WorldToLocal(const TinyObjPoint &a, const TinyObjPoint &u,
1477|                                 const TinyObjPoint &v, const TinyObjPoint &w) {
1478|  return TinyObjPoint(dot(a, u), dot(a, v), dot(a, w));
