2055|                            const std::string &filename) {
2056|  if (dir.empty()) {
2057|    return filename;
2058|  } else {
2059|    // check '/'
2060|    char lastChar = *dir.rbegin();
2061|    if (lastChar != '/') {
2062|      return dir + std::string("/") + filename;
2063|    } else {
2064|      return dir + filename;
2065|    }
2066|  }
