2150|      continue;
2151|    }
2152|
2153|    // ambient
2154|    if (token[0] == 'K' && token[1] == 'a' && IS_SPACE((token[2]))) {
2155|      token += 2;
2156|      real_t r, g, b;
2157|      parseReal3(&r, &g, &b, &token);
