2165|    if (token[0] == 'K' && token[1] == 'd' && IS_SPACE((token[2]))) {
2166|      token += 2;
2167|      real_t r, g, b;
2168|      parseReal3(&r, &g, &b, &token);
2169|      material.diffuse[0] = r;
2170|      material.diffuse[1] = g;
2171|      material.diffuse[2] = b;
